@push('scripts')<script>$(function(){var $table=$('#schedules-table'),text=$.fn.dataTable.render.text(),filters=function(){return {active:$('#schedule-active').val(),date_from:$('#schedule-date-from').val(),date_to:$('#schedule-date-to').val()};},states={OVERDUE:['เกินกำหนด','app-status-danger'],DUE_SOON:['ใกล้ครบกำหนด','app-status-warning'],UPCOMING:['ตามแผน','app-status-success']},table=$table.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:$table.data('url'),data:function(data){$.extend(data,filters());}},order:[[2,'asc']],buttons:[window.erpExcelButton($table)],columns:[{data:'asset_label',orderable:false,render:text.display},{data:'title',name:'title',render:text.display},{data:'next_due_date_label',name:'next_due_date',render:text.display},{data:'responsible_label',orderable:false,render:text.display},{data:'due_state',orderable:false,render:function(value,type){return type==='display'?'<span class="badge '+states[value][1]+'">'+states[value][0]+'</span>':value;}},{data:null,orderable:false,searchable:false,className:'text-end',render:function(_,type,row){if(type!=='display')return '';var actions=[];if(row.edit_url)actions.push('<a class="btn btn-sm btn-app-soft" href="'+text.display(row.edit_url)+'" title="แก้ไข" aria-label="แก้ไข"><i class="bx bx-edit" aria-hidden="true"></i></a>');if(row.complete_url)actions.push('<button class="btn btn-sm btn-app-primary js-schedule-complete" data-url="'+text.display(row.complete_url)+'" title="บันทึกดำเนินการแล้ว" aria-label="บันทึกดำเนินการแล้ว"><i class="bx bx-check" aria-hidden="true"></i></button>');return actions.join(' ');}}]}));$('#schedule-active,#schedule-date-from,#schedule-date-to').on('change',function(){table.ajax.reload();});$('#schedule-filter-reset').on('click',function(){$('#schedule-active,#schedule-date-from,#schedule-date-to').val('');table.ajax.reload();});$table.on('click','.js-schedule-complete',function(){var $button=$(this);Swal.fire({icon:'question',title:'บันทึกว่าดำเนินการแล้ว?',input:'date',inputValue:@json(today()->toDateString()),showCancelButton:true,confirmButtonText:'บันทึก',cancelButtonText:'ยกเลิก',preConfirm:function(value){if(!value)Swal.showValidationMessage('กรุณาเลือกวันที่');}}).then(function(result){if(!result.isConfirmed)return;$button.prop('disabled',true);$.post($button.data('url'),{_token:@json(csrf_token()),completed_date:result.value}).done(function(response){Swal.fire({icon:'success',title:response.msg});table.ajax.reload(null,false);}).fail(window.erpAjaxError).always(function(){$button.prop('disabled',false);});});});});</script>@endpush
